migration_common='Preserve the same input, output and failure category when porting. Template spelling alone is not the semantic contract.'
def migration(x):
 c=x['cpp']; d=x['d']; out=[]
 if 'metaml::Session' in c:out.append('C++ creates a noncopyable Session value; D allocates MetaML.Session as a class reference. Keep native callback captures alive for the whole session lifecycle and close resources explicitly at their owner boundary.')
 if 'isNull' in d:out.append('The C++ optional test becomes D Nullable.isNull, with the sense reversed. Test the outer parse result before accessing an inner optional payload; absence and parse failure can occupy different layers.')
 if 'new ' in d and 'Session' not in d:out.append('This D facility is a reference type, so construction uses new. Copying the reference aliases the same mutable object; it does not perform the AST-style deep copy demonstrated earlier.')
 if 'leaf!' in d or 'node!' in d:out.append('D accepts string template arguments directly. ASTNode remains a value with explicit deep-copy behavior, so changing a copied tree must not mutate the original. Keep tests for that behavior when upgrading the module.')
 if 'pipe(' in d or 'predicate(' in d:out.append('The D example uses a typed callable parameter. A generic callable can instead be supplied as an alias template argument. Preserve capture ownership when moving a local stage into long-lived application storage.')
 if 'r = s.eval' in d or 'r = candidate.eval' in d:out.append('The MetaML program text follows the same language rules in either host. Check the native Result before inspecting the language Value. A successful language value can itself encode a domain failure such as Err or false.')
 if 'StaticRegex' in d or 'BinaryStream' in d:out.append('Byte recognition and fixed-width fields must remain independent of native word size. D uint and ushort map to the explicit widths used here; choose byte order at each format boundary rather than inheriting machine endianness.')
 if not out:out.append('D uses module imports and exclamation-mark template instantiation where C++ uses includes, namespaces and angle brackets. The runnable file includes the required imports; the listing shows only its main body.')
 return ' '.join(out[:2])
source_map=[]
for i,ch in enumerate(cs,1):
 n=notes[i-1];t='\\chapter{'+esc(ch['title'])+'}\\label{ch:'+str(i)+'}\n'
 t+=h('The working problem')+para(ch['aim'])+para(ch['architecture'])
 t+=h(n[0])+para(n[1])
 t+=h('In this chapter')+'\\begin{enumerate}\n'+''.join('\\item '+esc(x['title'])+'\n' for x in ch['lessons'])+'\\end{enumerate}\n'
 t+=para('Read the workshops in order, then use the chapter review to connect the small examples to an application boundary. Each example is independently runnable; it does not depend on variables introduced in an earlier listing.')
 for j,x in enumerate(ch['lessons'],1):
  name=f'ex{i:02}_{j:02}'; langfile='MetaML.hpp' if ('metaml::' in x['cpp']) else 'DSLtk.hpp'
  lines=(R/'vendor'/langfile).read_text().splitlines();pat=re.compile(r'\b'+re.escape(x['anchor'])+r'\b'); found=next((k+1 for k,l in enumerate(lines) if pat.search(l) and not l.strip().startswith(('*','//'))),1)
  if x['anchor']=='Session' and langfile=='MetaML.hpp': found=next(k+1 for k,l in enumerate(lines) if l.strip()=='class Session')
  dfile='MetaML.d' if langfile=='MetaML.hpp' else 'DSLtk.d'
  dlines=(R/'vendor'/dfile).read_text().splitlines()
  dfound=next((k+1 for k,l in enumerate(dlines) if pat.search(l) and not l.strip().startswith(('*','//'))),1)
  source_map.append(f'| {name} | {x["title"]} | vendor/{langfile}:{found}; vendor/{dfile}:{dfound} | `{x["anchor"]}` |')
  t+='\\clearpage\n\\workshop{'+f'{i}.{j}'+ '}{'+esc(x['title'])+'}{C++20}\n'
  t+=para(x['concept'])
  t+=f'\\lstinputlisting[language=C++,caption={{Example {esc(name)}: C++}}]{{examples/cpp/{name}.inc}}\n'
  t+=h('Execution, step by step')+para(x['trace'])
  t+=h('Read the implementation')+para(f'The relevant source entry is {x["anchor"]} in vendor/{langfile}, around line {found}. Follow the public call into its result construction or dispatch branch. Identify the input ownership, the success condition and the exact failure path before changing this example.')
  t+=para('The assertions are the acceptance contract for this workshop. Run the complete program, then change one input at a time. When a change fails, first identify whether the failure belongs to the native build, structural recognition, language checking, execution or the domain result.')
  t+='\\clearpage\n\\workshop{'+f'{i}.{j}'+'}{'+esc(x['title'])+'}{D}\n'
  t+=para(migration(x))
  t+=f'\\lstinputlisting[language=D,caption={{Example {esc(name)}: D}}]{{examples/d/{name}.inc}}\n'
  t+=h('Failure and design boundary')+para(x['caution'])
  t+=h('Try it yourself')+para(x['exercise'])
  t+=h('Review the result')+para('Keep the original accepted fixture and add the new boundary fixture beside it. Compare observable values and diagnostic categories across the two hosts. Do not label the D run as passed until a D compiler has executed it; the supplied edition records source review separately from runtime evidence.')
  if 'ml' in x:t+=para(f'The shared language fixture is also available as examples/{name}.ml. Use that file when comparing native embeddings so escaping differences in host strings do not change the program being tested.')
 t+='\\clearpage\n'+h('Chapter review: '+n[0])+para(n[2])
 t+=h('Questions to answer in your implementation')+'\\begin{enumerate}\n'
 for x in ch['lessons']:t+='\\item '+esc(x['exercise'])+'\n'
 t+='\\end{enumerate}\n'
 t+=h('A practical completion test')+para('Choose one workshop and replace its fixed input with an application boundary: a command-line argument, a file, a configuration field or a typed callback. Write down the accepted input shape and the error outcome. Keep parsing and validation separate from publishing state. Preserve the smallest failing input when a regression is found.')
 if i in [23,24]:t+=para('The complete C++ and D programs are in case-studies/'+('formula' if i==23 else 'policy')+'/. They include the ownership and validation code omitted from the small workshop bodies. Run the case acceptance tests with make test-cases before extending the program.')
 (R/f'chapters/ch{i:02}.tex').write_text(t)
(R/'SOURCE-MAP.md').write_text('# Source snapshot and example anchors\n\nAll vendor files are byte-identical to the supplied attachments. Source line anchors identify entry points, not a claim that every associated operation is implemented on that line.\n\n| Canonical file | Original upload | SHA-256 |\n|---|---|---|\n'+''.join(f'| {f} | {o} | `{hashlib.sha256((R/"vendor"/f).read_bytes()).hexdigest()}` |\n' for f,o in [('DSLtk.hpp','DSLtk(3).hpp'),('DSLtk.d','DSLtk(1).d'),('MetaML.hpp','MetaML(2).hpp'),('MetaML.d','MetaML.d')])+'\n| Example | Topic | C++ source entry | Symbol |\n|---|---|---|---|\n'+'\n'.join(source_map)+'\n')
